 {id:5,date:"2026/08/16 15:30",name:"黃先生",company:"個人工坊",phone:"0955-123-456",email:"huang@example.com",line:"craft88",type:"雲端看帳",region:"台中市",status:"無用客",need:"了解雲端看帳年費與帳號數量。",hidden:false}
